import base64
import json
import os
from pathlib import Path
import runpy
import sys
import urllib.parse
import urllib.request

METADATA_ROOT = "http://metadata.google.internal/computeMetadata/v1"
METADATA_HEADERS = {"Metadata-Flavor": "Google"}


def get_json(url, headers):
    request = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(request, timeout=30) as response:
        return json.loads(response.read().decode("utf-8"))


token_payload = get_json(
    METADATA_ROOT + "/instance/service-accounts/default/token", METADATA_HEADERS
)
access_token = token_payload["access_token"]
secret_headers = {"Authorization": "Bearer " + access_token}
for environment_name, secret_name in {'HF_TOKEN': 'hf-token', 'WANDB_API_KEY': 'wandb-api-key'}.items():
    encoded_name = urllib.parse.quote(secret_name, safe="")
    payload = get_json(
        "https://secretmanager.googleapis.com/v1/projects/"
        + 'electric-armor-388216'
        + "/secrets/"
        + encoded_name
        + "/versions/latest:access",
        secret_headers,
    )
    os.environ[environment_name] = base64.b64decode(payload["payload"]["data"]).decode(
        "utf-8"
    )

FILES = json.loads("{\"remote_preflight.py\": \"\", \"contrast_sampler.py\": \"\", \"trl_sampler_adapter.py\": \"\"}")
SCRIPT_ARGS = json.loads("[\"--task\", \"gsm8k\", \"--arm\", \"contrast_early_stop_g2_to_g8\", \"--seed\", \"211\", \"--unit-fingerprint\", \"3cb9c063080074ad2604595058911a27197153644dcf3fcaa63a4f658ad7cfa8\", \"--stack-fingerprint\", \"0f6b41e5e20646ba79f54971956055761928301a87c01b5400dfb9e0ec6b742c\", \"--source-commit\", \"b522e32834ebebda4cc74608bca039ab93d7ad57\", \"--protocol-sha256\", \"8849fecf6ebbbc974907f3a43078a6ff25fcec3457b1c6b3c2dff662575b7d75\", \"--provider\", \"gcp_compute\", \"--hardware-flavor\", \"a2-highgpu-1g-spot\", \"--hf-repo\", \"arvindcr4/tinker-rl-next-preflight-gcp-gsm8k-contrast_ear-s211-3cb9c063\", \"--wandb-project\", \"tinker-rl-lab\", \"--wandb-group\", \"next-submission-preflight-gcp\", \"--wandb-run-name\", \"next-preflight-gcp-gsm8k-contrast_early_stop_g2_to_g8-s211-3cb9c063\"]")
source_root = Path("/opt/next-submission-preflight-source")
source_root.mkdir(parents=True, exist_ok=True)
for name, payload in FILES.items():
    (source_root / name).write_bytes(base64.b64decode(payload))
os.environ["NEXT_PREFLIGHT_SOURCE_ROOT"] = str(source_root)
os.environ["NEXT_PREFLIGHT_OUTPUT_DIR"] = "/var/lib/next-preflight/output"
os.environ["NEXT_PREFLIGHT_RESULT_PATH"] = "/var/lib/next-preflight/result.json"
os.environ["NEXT_PREFLIGHT_REPORT_TO"] = "wandb"
sys.path.insert(0, str(source_root))
script = source_root / "remote_preflight.py"
sys.argv = [str(script), *SCRIPT_ARGS]
runpy.run_path(str(script), run_name="__main__")
